const r = await tools.exec_command({cmd:". 'D:/hongmengcup/Enter-HarmonyEnv.ps1'
foreach($run in @('round02-t1-retry','round02-regression','round02-supplement')){
  $dir='traces/implementation-validation/'+$run
  $network=@(Get-Content -LiteralPath ($dir+'/webdav-requests.jsonl')|ForEach-Object {$_|ConvertFrom-Json})
  $ui=@(Get-Content -LiteralPath ($dir+'/ui-events.jsonl')|ForEach-Object {$_|ConvertFrom-Json})
  $requests=@($network|Where-Object {$_.event -eq 'request'});$responses=@($network|Where-Object {$_.event -eq 'response'})
